"""Collect every chapter's "Gaps" / "Limits" / "Still open" section into docs/OPEN-QUESTIONS.md:
one research agenda listing what the evidence could not settle, chapter by chapter.

usage: gen_gaps.py docs
"""
import os
import re
import sys

docs = sys.argv[1]
HEAD = re.compile(r'^(#{2,3}) .*(gap|limit|still open|unknown|not knowable|open question)', re.I)
out = ['# Open questions', '',
       'Everything the chapters could not settle from the restore image, kernel, firmware, dyld cache and public sources, '
       'collected from each chapter\'s gaps/limits sections (generated by `tools/gen_gaps.py`). '
       'This is the research agenda for anyone with a real device, a different build or more time.', '']
total = 0
for f in sorted(os.listdir(docs)):
    if not re.match(r'\d\d-.*\.md$', f):
        continue
    lines = open(os.path.join(docs, f)).read().split('\n')
    title = lines[0].lstrip('# ').strip()
    sections, i = [], 0
    while i < len(lines):
        m = HEAD.match(lines[i])
        if m:
            level = len(m.group(1))
            j = i + 1
            while j < len(lines) and not (lines[j].startswith('#') and len(lines[j]) - len(lines[j].lstrip('#')) <= level):
                j += 1
            body = [l for l in lines[i + 1:j] if l.strip()]
            anchor = re.sub(r'[^a-z0-9 -]', '', lines[i].lstrip('# ').lower()).replace(' ', '-')
            sections.append((lines[i].lstrip('# ').strip(), anchor, body))
            i = j
        else:
            i += 1
    if not sections:
        continue
    out += ['', f'## [{title}]({f})', '']
    for name, anchor, body in sections:
        items = sum(1 for l in body if re.match(r'\s*([-*]|\d+\.|\|)', l) and not l.startswith('|---'))
        total += items
        out += [f'### [{name}]({f}#{anchor})', ''] + body + ['']
out.insert(4, f'{total} open items across the chapters.')
open(os.path.join(docs, 'OPEN-QUESTIONS.md'), 'w').write('\n'.join(out) + '\n')
print(total, 'items')
